def get_digits(n):
    return [int(d) for d in str(n)]

def has_distinct_nonzero_digits(n):
    s = str(n)
    digits = [int(c) for c in s]
    return len(digits) == len(set(digits)) and all(d != 0 for d in digits)

def remove_digit(n, index):
    s = str(n)
    return int(s[:index] + s[index+1:])

memo = {}

def is_good(m):
    if m in memo:
        return memo[m]

    if not has_distinct_nonzero_digits(m):
        # This should not happen for inputs derived from the problem constraints, 
        # but ensures robustness.
        return False

    # Base case: single-digit number
    if m < 10:
        memo[m] = True
        return True

    digits = get_digits(m)

    for i in range(len(digits)):
        m_prime = remove_digit(m, i)

        # Check 1: m' must be a divisor of m
        if m % m_prime == 0:
            # Check 2: m' must be a good number
            if is_good(m_prime):
                memo[m] = True
                return True

    memo[m] = False
    return False

candidates = {
    'A': 98,
    'B': 96,
    'C': 975,
    'D': 9372
}

results = {}
print("--- Checking Candidates ---")
for label, m in candidates.items():
    result = is_good(m)
    print(f"Candidate {label} ({m}) is good: {result}")
    results[label] = result

